    expectTypeOf(err).toEqualTypeOf<HTTPError<unknown>>();
    problem({ status: 400 });
    // @ts-expect-error type must be a string
    problem({ status: 400, type: 1 });
    expectTypeOf(problem({ data: { a: 1 } })).toEqualTypeOf<HTTPError<{ a: number }>>();
  });

  it("exports TypedHeaders", () => {
    type RequestHeaders = TypedHeaders<{ authorization: string }>;
