import type { HTTPError } from "../../error.ts";

export type ProblemMark = { type?: string; instance?: string };

export function getProblemMark(error: HTTPError): ProblemMark | undefined {
  return (error as any)["~problem"];
}

export function problemBody(
  error: HTTPError,
  mark: ProblemMark,
  debug?: boolean,
): Record<string, unknown> {
  const type = mark.type ?? "about:blank";
  const unhandled = error.unhandled;
  return {
    ...(unhandled ? undefined : error.body),
    data: unhandled ? undefined : error.data,
    type,
    title: error.statusText || (type === "about:blank" ? statusPhrases[error.status] : undefined),
    status: error.status,
    detail: error.toJSON().message,
    instance: mark.instance,
    stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
  };
}

const statusPhrases: Record<number, string> = {
  400: "Bad Request",
  401: "Unauthorized",
  403: "Forbidden",
  404: "Not Found",
  405: "Method Not Allowed",
  406: "Not Acceptable",
  408: "Request Timeout",
  409: "Conflict",
  410: "Gone",
  412: "Precondition Failed",
  413: "Payload Too Large",
  415: "Unsupported Media Type",
  418: "I'm a Teapot",
  422: "Unprocessable Content",
  429: "Too Many Requests",
  500: "Internal Server Error",
  501: "Not Implemented",
  502: "Bad Gateway",
  503: "Service Unavailable",
  504: "Gateway Timeout",
};

import { HTTPError, type ErrorInput } from "../error.ts";

export interface ProblemInput<DataT = unknown> extends ErrorInput<DataT> {
  /** URI reference identifying the problem type. Defaults to `"about:blank"`. */
  type?: string;
  /** URI reference identifying this specific occurrence of the problem. */
  instance?: string;
}

/**
 * Create an `HTTPError` that is responded to as RFC 9457 `application/problem+json`.
 *
 * `message` maps to `detail`, `statusText` to `title` and `body` to extension members.
 *
 * Note: `type` and `instance` are kept even when `unhandled` is set, do not interpolate internal data into them.
 *
 * @example
 *
 * throw problem({ status: 404, type: "https://example.com/not-found", message: "User 42 not found" })
 */
export function problem<DataT = unknown>(input: ProblemInput<DataT>): HTTPError<DataT> {
  const { type, instance, ...rest } = input;
  const error = new HTTPError<DataT>(rest);
  Object.defineProperty(error, "~problem", { value: { type, instance } });
  return error;
}

import { HTTPError, type ErrorInput } from "../error.ts";

export interface ProblemInput<DataT = unknown> extends ErrorInput<DataT> {
  /** URI reference identifying the problem type. Defaults to `"about:blank"`. */
  type?: string;
  /** URI reference identifying this specific occurrence of the problem. */
  instance?: string;
}

/**
 * Create an `HTTPError` that is responded to as RFC 9457 `application/problem+json`.
 *
 * `message` maps to `detail`, `statusText` to `title` and `body` to extension members.
 *
 * Note: `type` and `instance` are kept even when `unhandled` is set, do not interpolate internal data into them.
 *
 * @example
 *
 * throw problem({ status: 404, type: "https://example.com/not-found", message: "User 42 not found" })
 */
export function problem<DataT = unknown>(input: ProblemInput<DataT>): HTTPError<DataT> {
  const { type, instance, ...rest } = input;
  const error = new HTTPError<DataT>(rest);
  const mark: ProblemMark = { type, instance, body: problemBody };
  Object.defineProperty(error, "~problem", { value: mark });
  return error;
}

import { FastResponse } from "srvx";
import { HTTPError } from "./error.ts";
import { isJSONSerializable } from "./utils/internal/object.ts";
import { sanitizeStatusCode, sanitizeStatusMessage } from "./utils/sanitize.ts";
import { getProblemMark, problemBody } from "./utils/internal/problem.ts";
import { kEventDispose, type DisposeState } from "./utils/internal/dispose.ts";

import type { H3Config } from "./types/h3.ts";
import { kEventRes, kEventResHeaders, kEventResErrHeaders, type H3Event } from "./event.ts";

export const kNotFound: symbol = /* @__PURE__ */ Symbol.for("h3.notFound");
export const kHandled: symbol = /* @__PURE__ */ Symbol.for("h3.handled");

export function toResponse(
  val: unknown,
  event: H3Event,
  config: H3Config = {},
): Response | Promise<Response> {
  if (typeof (val as PromiseLike<unknown>)?.then === "function") {
    return (val as Promise<unknown>).then(
      (resolvedVal) => toResponse(resolvedVal, event, config),
      (r) => toResponse(toError(r), event, config),
    ) as Promise<Response>;
  }

  let response: Response | Promise<Response>;
  try {
    response = prepareResponse(val, event, config);
  } catch (error) {
    return toResponse(toError(error), event, config);
  }
  if (typeof (response as PromiseLike<Response>)?.then === "function") {
    return toResponse(response, event, config);
  }

  const { onResponse } = config;
  if (onResponse) {
    // onResponse is a terminal side-effect hook (returns void). A throw/rejection here must not
    // escape the lifecycle (onError already ran); absorb and log it (consistent with dispose
    // callbacks), then still return the already-built response. The hook is invoked inside `.then`
    // so a synchronous throw is caught too (not just a rejected promise).
    return Promise.resolve()
      .then(() => onResponse(response as Response, event))
      .catch((error) => {
        if (!config.silent) console.error(error);
      })
      .then(
        () =>
          ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
            response as Response,
            val,
          ) ?? (response as Response),
      );
  }
  return (
    ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
      response as Response,
      val,
    ) ?? (response as Response)
  );
}

/**
 * Normalize a thrown or rejected value before rendering it as a response.
 *
 * Errors and the internal sentinels are passed through, and numbers are coerced to a status code
 * (`throw 404`). Anything else — an object, a string, `undefined` — is wrapped into an unhandled
